class Solution:
    def isDecomposable(self, s: str) -> bool:
        runs = []
        i, n = 0, len(s)
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append(j - i)
            i = j
        used_two = False
        for r in runs:
            if r % 3 == 1:
                return False
            if r % 3 == 2:
                if used_two:
                    return False
                used_two = True
        return used_two

