class Solution {
public:
    bool isDecomposable(string s) {
        vector<int> runs;
        int i = 0, n = s.size();
        while (i < n) {
            int j = i;
            while (j < n && s[j] == s[i]) j++;
            runs.push_back(j - i);
            i = j;
        }
        bool usedTwo = false;
        for (int r : runs) {
            if (r % 3 == 1) return false;
            if (r % 3 == 2) {
                if (usedTwo) return false;
                usedTwo = true;
            }
        }
        return usedTwo;
    }
};

